148	func TestReadPathBridgeReadsNothingWhenThereIsNoBridgeToFind(t *testing.T) {
149		stopped := netCtr("app_net", testNetID)
150		stopped.Running = false
151		ambiguous := netCtr("app_net", testNetID)
152		ambiguous.Networks = append(ambiguous.Networks, docker.EndpointNetwork{
153			Name: "b_net", NetworkID: testNetID, Gateway: netip.MustParseAddr("172.19.0.1"),
154		})
155		tests := []struct {
156			name string
157			ctr  docker.ContainerNetworking
158			want pathBridge
159		}{
160			{"stopped", stopped, pathBridge{}},
161			{"host mode", netCtr("host", testNetID), pathBridge{}},
162			{"none mode", netCtr("none", testNetID), pathBridge{}},
163			{"shared namespace", netCtr("container:abc", testNetID), pathBridge{}},
164			{"undetermined (network equality)", ambiguous, pathBridge{}},
165			// A route exists but the network cannot be read without an ID.
166			{"empty network id", netCtr("app_net", ""), pathBridge{State: bridgeUnverified}},
167			{"zero value", docker.ContainerNetworking{}, pathBridge{}},
168		}
169		for _, tc := range tests {
170			t.Run(tc.name, func(t *testing.T) {
171				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
172				if got := readPathBridge(context.Background(), tc.ctr, bridgeTimout, f.engine()); got != tc.want {
173					t.Fatalf("bridge = %+v, want %+v", got, tc.want)
174				}
175				if f.networkCalls != 0 || f.ifacesCalls != 0 {
176					t.Fatalf("network calls %d, interfaces calls %d, want 0 and 0", f.networkCalls, f.ifacesCalls)
177				}
178			})
179		}
180	}
