236	// A failed read shows nothing, is logged raw with the package prefix, and the
237	// trace runs to its end.
238	func TestPathBridgeReadFailureIsLoggedNotShown(t *testing.T) {
239		tests := []struct {
240			name string
241			fake func() *fakeEngine
242			raw  string
243		}{
244			{"network read fails", func() *fakeEngine {
245				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
246				f.networkErr = errors.New("net-boom-raw")
247				return f
248			}, "net-boom-raw"},
249			{"interface list fails", func() *fakeEngine {
250				f := bridgeFake("docker0")
251				f.ifacesErr = errors.New("if-boom-raw")
252				return f
253			}, "if-boom-raw"},
254		}
255		for _, tc := range tests {
256			t.Run(tc.name, func(t *testing.T) {
257				f := tc.fake()
258				logs := captureLog(t)
259				pm := pmWith(t, f)
260				pm.source = webSource
261				pm, cmd := launched(t, pm, "1.1.1.1")
262				for _, msg := range testutil.Msgs(cmd) {
263					pm, _ = pmFeed(t, pm, msg)
264				}
265				for msg := range pm.msgs {
266					pm, _ = pmFeed(t, pm, msg)
267				}
268	
269				requireBridge(t, pm, "")
270				if f.traceCalls != 1 || pm.state != pathDone || !slices.Equal(pmHopTTLs(pm), []int{1}) {
271					t.Fatalf("traceCalls=%d state=%v hops=%v, want the trace carried to its end", f.traceCalls, pm.state, pmHopTTLs(pm))
272				}
273				if !strings.Contains(logs.String(), "ERROR [netdiag/path] ") || !strings.Contains(logs.String(), tc.raw) {
274					t.Fatalf("log %q lacks an ERROR [netdiag/path] line with %q", logs.String(), tc.raw)
275				}
276				if strings.Contains(pm.footer.Text(), tc.raw) || strings.Contains(pm.statusLine().Text, tc.raw) || pm.errText != "" {
277					t.Fatalf("the raw error reached the screen: footer %q status %q err %q", pm.footer.Text(), pm.statusLine().Text, pm.errText)
278				}
279			})
280		}
281	}
