283	// esc during the read is not a failure: nothing is logged.
284	func TestPathBridgeCanceledReadIsNotLogged(t *testing.T) {
285		t.Run("readPathBridge", func(t *testing.T) {
286			ctx, cancel := context.WithCancel(context.Background())
287			defer cancel()
288			f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
289			e := f.engine()
290			e.network = func(ctx context.Context, _ string) (docker.NetworkBridge, error) {
291				cancel()
292				return docker.NetworkBridge{}, fmt.Errorf("canceled sentinel: %w", ctx.Err())
293			}
294			logs := captureLog(t)
295			if got := readPathBridge(ctx, netCtr("app_net", testNetID), bridgeTimout, e); got != (pathBridge{State: bridgeUnverified}) {
296				t.Fatalf("bridge = %+v, want Unverified", got)
297			}
298			if strings.Contains(logs.String(), "sentinel") {
299				t.Fatalf("a canceled read was logged: %q", logs.String())
300			}
301		})
302		t.Run("producer", func(t *testing.T) {
303			ctx, cancel := context.WithCancel(context.Background())
304			defer cancel()
305			f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
306			e := f.engine()
307			e.interfaces = func(ctx context.Context) ([]netiface.Interface, error) {
308				cancel() // esc during the read
309				return nil, fmt.Errorf("canceled sentinel: %w", ctx.Err())
310			}
311			logs := captureLog(t)
312			msgs := runProducerFrom(t, ctx, 1, pathTarget{Host: "10.0.0.8"}, webSource, time.Second, e)
313	
314			if strings.Contains(logs.String(), "sentinel") {
315				t.Fatalf("a canceled read was logged: %q", logs.String())
316			}
317			if _, ok := msgs[len(msgs)-1].(pathDoneMsg); !ok {
318				t.Fatalf("last = %#v, want a done message", msgs[len(msgs)-1])
319			}
320		})
321	}
