323	// The network is read by its ID, never by its name (a name could be taken for
324	// an option by the CLI), under a deadline.
325	func TestPathBridgeReadsByIDUnderATimeout(t *testing.T) {
326		f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
327		got := readPathBridge(context.Background(), netCtr("app_net", testNetID), bridgeTimout, f.engine())
328	
329		if want := (pathBridge{State: bridgeFound, Name: "docker0"}); got != want {
330			t.Fatalf("bridge = %+v, want %+v", got, want)
331		}
332		if !slices.Equal(f.networkIDs, []string{testNetID}) {
333			t.Fatalf("network ids = %v, want [%s]", f.networkIDs, testNetID)
334		}
335		if slices.Contains(f.networkIDs, testNetName) {
336			t.Fatal("the network was read by its name")
337		}
338		dl, ok := f.networkCtx.Deadline()
339		if !ok {
340			t.Fatal("network context carries no deadline")
341		}
342		if left := time.Until(dl); left > bridgeTimout || left <= 0 {
343			t.Fatalf("network deadline in %v, want within (0, %v]", left, bridgeTimout)
344		}
345	}
