347	// The gateway used is the one of the default-route endpoint, not of another.
348	func TestReadPathBridgeUsesTheDefaultRouteEndpoint(t *testing.T) {
349		n := docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "a_net", Networks: []docker.EndpointNetwork{
350			{Name: "a_net", NetworkID: "id-a", Gateway: netip.MustParseAddr("172.18.0.1"), GwPriority: prioOf(0)},
351			{Name: "b_net", NetworkID: "id-b", Gateway: netip.MustParseAddr("172.19.0.1"), GwPriority: prioOf(10)},
352		}}
353		f := bridgeFake("br-b", ifaceWith("br-a", "172.18.0.1/16"), ifaceWith("br-b", "172.19.0.1/16"))
354		got := readPathBridge(context.Background(), n, bridgeTimout, f.engine())
355	
356		if got != (pathBridge{State: bridgeFound, Name: "br-b"}) || !slices.Equal(f.networkIDs, []string{"id-b"}) {
357			t.Fatalf("bridge = %+v, ids = %v, want br-b read by id-b", got, f.networkIDs)
358		}
359	}
