361	func TestRouteEndpoint(t *testing.T) {
362		one := netCtr("app_net", testNetID)
363		tests := []struct {
364			name   string
365			in     docker.ContainerNetworking
366			wantOK bool
367			want   string
368		}{
369			{"attached to one network", one, true, testNetName},
370			{"host", netCtr("host", testNetID), false, ""},
371			{"none", netCtr("none", testNetID), false, ""},
372			{"shared", netCtr("container:abc", testNetID), false, ""},
373			{"no gateway", docker.ContainerNetworking{Mode: "app_net", Networks: []docker.EndpointNetwork{{Name: "x"}}}, false, ""},
374			{"zero value", docker.ContainerNetworking{}, false, ""},
375		}
376		for _, tc := range tests {
377			t.Run(tc.name, func(t *testing.T) {
378				got, ok := routeEndpoint(tc.in)
379				if ok != tc.wantOK || got.Name != tc.want {
380					t.Fatalf("routeEndpoint = (%q, %v), want (%q, %v)", got.Name, ok, tc.want, tc.wantOK)
381				}
382			})
383		}
384		// newPathContainer agrees with it.
385		if ep, ok := routeEndpoint(one); !ok {
386			t.Fatal("precondition")
387		} else if c := newPathContainer(webSource, one, nil); c.Attach != attachNetwork || c.Gateway != ep.Gateway {
388			t.Fatalf("newPathContainer %+v disagrees with routeEndpoint %+v", c, ep)
389		}
390	}
