392	// The name is display-safe like every other engine text: a control or escape
393	// sequence in an interface name never reaches a cell.
394	func TestPathBridgeNameIsDisplaySafe(t *testing.T) {
395		const raw = "dock\x1b[31mer0\n\x07"
396		f := bridgeFake(raw, ifaceWith(raw, testGateway+"/16"))
397	
398		if got := readPathBridge(context.Background(), netCtr("app_net", testNetID), bridgeTimout, f.engine()); got.State != bridgeFound || got.Name != "docker0" {
399			t.Fatalf("bridge = %+v, want Found docker0", got)
400		}
401	
402		pm := bridgeRun(t, bridgeFake(raw, ifaceWith(raw, testGateway+"/16")))
403		requireBridge(t, pm, "docker0")
404		for _, s := range pm.table.Items() {
405			if strings.ContainsAny(s.addressCell(), "\x1b\x07\n") {
406				t.Fatalf("row %q carries a control character", s.addressCell())
407			}
408		}
409	}
