411	// The resolved message carries the bridge and the model puts it in the column.
412	func TestPathResolvedCarriesTheBridge(t *testing.T) {
413		f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
414		msgs := runProducerFrom(t, context.Background(), 1, pathTarget{Host: "1.1.1.1"}, webSource, time.Second, f.engine())
415	
416		res, ok := msgs[0].(pathResolvedMsg)
417		if !ok || res.bridge != (pathBridge{State: bridgeFound, Name: "docker0"}) {
418			t.Fatalf("msgs[0] = %#v, want a resolved message with bridge Found docker0", msgs[0])
419		}
420	
421		pm := pmWith(t, f)
422		pm.source = webSource
423		pm, _ = launched(t, pm, "1.1.1.1")
424		pm, _ = pmFeed(t, pm,
425			pathResolvedMsg{gen: pm.gen, addr: netip.MustParseAddr("1.1.1.1"), route: defaultRouteHop(), source: webSource, ctr: f.inspectNet, bridge: pathBridge{State: bridgeFound, Name: "docker0"}},
426			pathHopMsg{gen: pm.gen, hop: hopAt(1)},
427		)
428		requireBridge(t, pm, "docker0")
429	}
