431	// DEVDESK-332 step 1: readPathBridge reports a state, not only a name.
432	func TestReadPathBridgeStates(t *testing.T) {
433		tests := []struct {
434			name      string
435			fake      func() *fakeEngine
436			want      pathBridge
437			wantIface int
438			wantLog   string
439		}{
440			{"interface carries the gateway", func() *fakeEngine {
441				return bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
442			}, pathBridge{State: bridgeFound, Name: "docker0"}, 1, ""},
443			{"no interface of that name", func() *fakeEngine {
444				return bridgeFake("docker0", ifaceWith("eth0", "192.168.1.21/24"))
445			}, pathBridge{State: bridgeAbsent}, 1, ""},
446			{"interface without the gateway", func() *fakeEngine {
447				return bridgeFake("docker0", ifaceWith("docker0", "10.9.0.1/16"))
448			}, pathBridge{State: bridgeUnverified}, 1, ""},
449			{"empty name (macvlan)", func() *fakeEngine {
450				return bridgeFake("", ifaceWith("docker0", testGateway+"/16"))
451			}, pathBridge{State: bridgeUnverified}, 0, ""},
452			{"network read fails", func() *fakeEngine {
453				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
454				f.networkErr = errors.New("net-boom-raw")
455				return f
456			}, pathBridge{State: bridgeUnverified}, 0, "net-boom-raw"},
457			{"interface list fails", func() *fakeEngine {
458				f := bridgeFake("docker0")
459				f.ifacesErr = errors.New("if-boom-raw")
460				return f
461			}, pathBridge{State: bridgeUnverified}, 1, "if-boom-raw"},
462		}
463		for _, tc := range tests {
464			t.Run(tc.name, func(t *testing.T) {
465				f := tc.fake()
466				logs := captureLog(t)
467				got := readPathBridge(context.Background(), netCtr("app_net", testNetID), bridgeTimout, f.engine())
468				if got != tc.want {
469					t.Fatalf("bridge = %+v, want %+v", got, tc.want)
470				}
471				if f.ifacesCalls != tc.wantIface {
472					t.Fatalf("interfaces calls = %d, want %d", f.ifacesCalls, tc.wantIface)
473				}
474				if tc.wantLog == "" {
475					if strings.Contains(logs.String(), "ERROR [netdiag/path]") {
476						t.Fatalf("unexpected error log %q", logs.String())
477					}
478					return
479				}
480				if !strings.Contains(logs.String(), "ERROR [netdiag/path] ") || !strings.Contains(logs.String(), tc.wantLog) {
481					t.Fatalf("log %q lacks an ERROR [netdiag/path] line with %q", logs.String(), tc.wantLog)
482				}
483			})
484		}
485	}
