496	// A canceled run logs nothing, whichever read was interrupted.
497	func TestReadPathBridgeCanceledInterfacesIsUnverifiedAndSilent(t *testing.T) {
498		ctx, cancel := context.WithCancel(context.Background())
499		defer cancel()
500		f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
501		e := f.engine()
502		e.interfaces = func(ctx context.Context) ([]netiface.Interface, error) {
503			cancel()
504			return nil, fmt.Errorf("canceled sentinel: %w", ctx.Err())
505		}
506		logs := captureLog(t)
507		if got := readPathBridge(ctx, netCtr("app_net", testNetID), bridgeTimout, e); got.State != bridgeUnverified {
508			t.Fatalf("bridge = %+v, want Unverified", got)
509		}
510		if strings.Contains(logs.String(), "sentinel") {
511			t.Fatalf("a canceled read was logged: %q", logs.String())
512		}
513	}
514

