28	// netCtr is a running container on one network, whose endpoint carries id.
29	func netCtr(mode, id string) docker.ContainerNetworking {
30		return docker.ContainerNetworking{
31			Name: "web-1", Running: true, Mode: mode,
32			Networks: []docker.EndpointNetwork{{
33				Name: testNetName, NetworkID: id,
34				IPv4:    netip.MustParseAddr("172.18.0.5"),
35				Gateway: netip.MustParseAddr(testGateway),
36			}},
