55	// bridgeRun launches a trace of 1.1.1.1 from the web-1 source and feeds every
56	// message of the producer to the model.
57	func bridgeRun(t *testing.T, f *fakeEngine) *PathModel {
58		t.Helper()
59		captureLog(t)
60		pm := pmWith(t, f)
61		pm.source = webSource
62		pm, cmd := launched(t, pm, "1.1.1.1")
63		for _, msg := range testutil.Msgs(cmd) {
64			pm, _ = pmFeed(t, pm, msg)
65		}
66		for msg := range pm.msgs {
67			pm, _ = pmFeed(t, pm, msg)
68		}
69		return pm
70	}
