			if f.networkCalls != 0 || f.ifacesCalls != 0 {
				t.Fatalf("network calls %d, interfaces calls %d, want 0 and 0", f.networkCalls, f.ifacesCalls)
			}
			if pm.state != pathDone {
				t.Fatalf("state = %v, want pathDone", pm.state)
			}
		})
	}

